// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: amount sent and caller
    function testFuzz_property(uint256 sendAmount, address actor) public {
        // Keep actor non-zero and amount in a wide range including values >, ==, < 10 ether
        vm.assume(actor != address(0));

        // ensure actor has sufficient balance for large fuzzed amounts
        uint256 capAmount = bound(sendAmount, 0, 100 ether);
        vm.deal(actor, capAmount);

        // Pick a block timestamp and block number where behavior is observable
        // Keep wide: warp to an increasing timestamp relative to initial pastBlockTime = 0
        uint64 ts = uint64(bound(uint256(block.timestamp) + 1, block.timestamp + 1, block.timestamp + 1000));
        vm.warp(ts);

        // Also pick a block number; keep it wide so sometimes divisible by 15
        uint64 bn = uint64(bound(block.number + 1, block.number + 1, block.number + 100));
        vm.roll(bn);

        // Call fallback through calldata-empty low-level call by invoking receive via c.fallback() style
        // The contract's fallback is external payable and will run when we call via low-level with empty data.

        bool ok;
        vm.prank(actor);
        // use try/catch to capture whether the call succeeded (reference reverts unless amount == 10 ether)
        try c.call{value: capAmount}("") returns (bytes memory) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call completes, the reference C guarantees: if the call succeeded then pastBlockTime == block.timestamp + 1.
        // We assert that property by reading c.pastBlockTime() and comparing to block.timestamp + 1 when call succeeded.
        // This assertion is true for the reference contract for all inputs, but the mutant (allowing >= 10 ether)
        // can succeed on calls with capAmount > 10 ether and thus produce different behaviors for some inputs.

        // Single assertion required: the property observed on c after the call.
        if (ok) {
            // when call succeeded, pastBlockTime must equal block.timestamp + 1
            assertTrue(c.pastBlockTime() == uint256(block.timestamp) + 1);
        } else {
            // when call reverted, pastBlockTime must remain 0 (constructor set to 0)
            // In the reference, any revert means fallback didn't run so pastBlockTime == 0
            assertTrue(c.pastBlockTime() == 0);
        }
    }
}

