pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: caller address and an initial priorTime to set up pastBlockTime,
    // and a block timestamp to warp to for the call. The fuzzer will search values.
    function testFuzz_property(address caller, uint256 priorTime, uint256 callTime) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // ensure we can fund the caller
        vm.deal(caller, 20 ether);

        // 1) establish an initial pastBlockTime by directly invoking fallback once from a controlled time
        // We need priorTime to be strictly less than the call time we'll use, so allow broad domain but
        // restrict extremely large values to avoid overflow issues with vm.warp (not necessary but safe)
        priorTime = bound(priorTime, 0, type(uint64).max);
        callTime = bound(callTime, 1, type(uint64).max); // callTime must be >=1 to allow prior < call

        // Set blockchain time to priorTime and make an initial valid call to set pastBlockTime
        vm.warp(priorTime);
        // perform an initial successful call: must pay exactly 10 ether and satisfy require(block.timestamp > pastBlockTime)
        // Since pastBlockTime starts at 0, any priorTime >=1 will satisfy > 0; ensure priorTime >=1 by bound above
        vm.prank(caller);
        c.f{value: 10 ether}();

        // read the stored value after the first call
        uint256 storedAfterFirst = c.pastBlockTime();

        // Now advance to callTime which must be > previous stored value's base to satisfy require
        // To allow a meaningful distinguishing scenario, ensure callTime > priorTime so block.timestamp increases
        vm.assume(callTime > priorTime);
        vm.warp(callTime);

        // perform the second fallback call from same caller paying exact 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        // After the second call, read the stored value again
        uint256 storedAfterSecond = c.pastBlockTime();

        // General rule the correct contract satisfies: after a successful fallback call at time T, pastBlockTime >= T + 1
        // and therefore strictly greater than any prior T used; express as: storedAfterSecond > storedAfterFirst
        // This must hold for the reference implementation for all admissible inputs above.
        // The mutant that sets pastBlockTime = block.timestamp can make storedAfterSecond == callTime,
        // which in some sequences may equal storedAfterFirst (or not strictly greater), so the assertion will fail
        // for such inputs. We assert the strict increase property below.
        assertTrue(storedAfterSecond > storedAfterFirst);
    }
}

