        vm.assume(payer != address(0));

        // give payer enough ETH
        vm.deal(payer, 20 ether);

        // ensure we start at a known timestamp
        vm.warp(1000);

        // first call: payer sends exactly 10 ether; this must succeed on reference
        vm.startPrank(payer);
        c.f{value: 10 ether}();
        vm.stopPrank();

        // read the recorded pastBlockTime after first call
