        vm.warp(block.timestamp + boundedDelta);

        // advance block number a bit to avoid same-block edgecases; keep it minimal
        vm.roll(block.number + 1);

        // second call: same payer sends exactly 10 ether again
        vm.startPrank(payer);
        c.f{value: 10 ether}();
        vm.stopPrank();

        uint256 second = c.pastBlockTime();

        // General rule: reference C enforces that second > first (monotonic increase), because it required
        // block.timestamp > pastBlockTime before updating. The mutant that removed that require can allow
        // second <= first when time did not advance (boundedDelta == 0), so this assertion will fail on the mutant
        assertTrue(second > first);
    }
}

