contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: timestamp to warp to before calling, and caller address
    function testFuzz_property(uint256 warpTime, address caller) public {
        // Keep warpTime in a reasonable wide range but allow non-increasing times
        warpTime = bound(warpTime, 0, type(uint256).max - 1);
        // make sure caller is a usable EOA
        vm.assume(caller != address(0));

        // Fund the caller so they can send 10 ether
        vm.deal(caller, 20 ether);

        // Arrange: set contract pastBlockTime to some value by making an initial valid call
        // Warp to an initial time and perform a valid call that sets pastBlockTime = warp0 + 1
        uint256 warp0 = block.timestamp + 1;
        vm.warp(warp0);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Now warp to the fuzzed time (which may be <= previous time). This is the deciding value.
        // The reference contract requires block.timestamp > pastBlockTime (which is warp0+1), so
        // if warpTime <= pastBlockTime the reference will revert; the mutant will not revert and will
        // update pastBlockTime to warpTime+1, causing divergence in stored value.
        vm.warp(warpTime);

        // Try calling fallback and record whether it succeeded (reference will revert for non-increasing time)
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call succeeded, then c.pastBlockTime() == block.timestamp + 1.
        // This holds for the reference for every admissible input; the mutant can make the call succeed when
        // block.timestamp <= prior pastBlockTime and therefore set pastBlockTime to a value that the
        // reference would not allow, causing the assertion to fail on the mutant for some fuzz input.
        if (ok) {
            assertTrue(c.pastBlockTime() == block.timestamp + 1);
        } else {
            // If call reverted, the reference also reverts in these cases; still assert a true constant path
            // by asserting that pastBlockTime was not changed (it remains > block.timestamp)
            assertTrue(c.pastBlockTime() > block.timestamp);
        }
    }
}

